const S=[-3.5,1];const L=(x,z)=>0.5*(x*x+4*z*z);
function rn(s){s=Math.sin(s*12.9898+78.233)*43758.5453;return s-Math.floor(s)}
function gs(s){const u=Math.max(rn(s),1e-6),v=rn(s+0.5);const r=Math.sqrt(-2*Math.log(u));return[r*Math.cos(6.2832*v),r*Math.sin(6.2832*v)]}
function sig(i){const B=+i.batchSize;return 3*Math.sqrt((256-B)/(255*B))}
function grad(st,i,seed){const n=gs(seed*1000+st.k*7.13+1);const s=sig(i);return[st.w[0]+s*n[0],4*st.w[1]+s*n[1]]}
export function initialState({inputs,seed}){return{w:S.slice(),k:0,c:0,tr:[],kp:[],div:false}}
function fresh(st){return{w:S.slice(),k:0,c:0,tr:[],kp:st.kp,div:false}}
export function reduce({state,event,inputs,seed}){if(event.type==='parameter')return fresh(state);if(event.type==='action'&&event.id==='keepPath'){const n=fresh(state);n.kp=state.tr.slice();return n}
if(event.type!=='step'||state.k>=40||state.div)return state;const c=state.c+1;if(c<6)return{...state,c};const g=grad(state,inputs,seed);const lr=inputs.learningRate;const w=[state.w[0]-lr*g[0],state.w[1]-lr*g[1]];const k=state.k+1;const tr=k%2===0?state.tr.concat([w]):state.tr;return{...state,w,k,c:0,tr,div:L(w[0],w[1])>10}}
function q(dx,dz){const m=Math.hypot(dx,dz)||1;const x=dz/m,z=-dx/m;const n=Math.hypot(x,z,1);return[x/n,0,z/n,1/n]}
const P=(w,o)=>{const l=Math.min(L(w[0],w[1]),12);return[w[0],0.25*l+o,w[1]]};
export function evaluate({inputs,state,seed}){const st=state||initialState({inputs,seed});const N={};const w=st.w;const bp=P(w,0.18);N.ball={position:bp};N.bl={text:st.div?'Diverged':'Weights'};for(let j=0;j<20;j++){const a=st.tr[j],b=st.kp[j];N['t'+j]=a?{visible:true,position:P(a,0.05)}:{visible:false};N['k'+j]=b?{visible:true,position:P(b,0.05)}:{visible:false}}
const done=st.k>=40||st.div;const g=grad(st,inputs,seed);const lr=inputs.learningRate;const sx=-lr*g[0],sz=-lr*g[1];const sl=Math.hypot(sx,sz)||1;const ap=[bp[0]+0.2*sx/sl,bp[1]+0.05,bp[2]+0.2*sz/sl];N.sa={visible:!done,position:ap,quaternion:q(sx,sz),scale:[1,Math.max(4*sl,0.25),1]};N.fa={visible:!done&&inputs.showTrueGradient,position:[bp[0],bp[1]+0.05,bp[2]],quaternion:q(-w[0],-4*w[1]),scale:[1,1,1]};
return{nodes:N,readouts:{loss:L(w[0],w[1]),stepN:st.k,dist:Math.hypot(w[0],w[1]),noise:sig(inputs)}}}
